  'log.allSeverities': { en: 'All severities', hi: 'सभी गंभीरताएं', es: 'Todas las gravedades', ta: 'அனைத்து தீவிரங்களும்', te: 'అన్ని తీవ్రతలు', kn: 'ಎಲ್ಲಾ ತೀವ್ರತೆಗಳು', ml: 'എല്ലാ തീവ്രതകളും' },
  'log.info': { en: 'Info', hi: 'जानकारी', es: 'Info', ta: 'தகவல்', te: 'సమాచారం', kn: 'ಮಾಹಿತಿ', ml: 'വിവരം' },
  'log.warn': { en: 'Warn', hi: 'चेतावनी', es: 'Advertencia', ta: 'எச்சரிக்கை', te: 'హెచ్చరిక', kn: 'ಎಚ್ಚರಿಕೆ', ml: 'മുന്നറിയിപ്പ്' },
  'log.error': { en: 'Error', hi: 'त्रुटि', es: 'Error', ta: 'பிழை', te: 'లోపం', kn: 'ದೋಷ', ml: 'പിശക്' },
