  'log.noEvents': { en: 'No events match this filter.', hi: 'इस फ़िल्टर से कोई घटना मेल नहीं खाती।', es: 'Ningún evento coincide con este filtro.', ta: 'இந்த வடிகட்டியுடன் நிகழ்வுகள் எதுவும் பொருந்தவில்லை.', te: 'ఈ ఫిల్టర్‌తో ఈవెంట్‌లు ఏవీ సరిపోలలేదు.', kn: 'ಈ ಫಿಲ್ಟರ್‌ಗೆ ಯಾವುದೇ ಘಟನೆಗಳು ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.', ml: 'ഈ ഫിൽട്ടറുമായി ഇവന്റുകളൊന്നും പൊരുത്തപ്പെടുന്നില്ല.' },
  'log.correlation': { en: 'correlation:', hi: 'सहसंबंध:', es: 'correlación:', ta: 'தொடர்பு:', te: 'కోరిలేషన్:', kn: 'ಸಂಬಂಧ:', ml: 'കോറിലേഷൻ:' },

