  'recovery.eyebrow': { en: 'Operations', hi: 'संचालन', es: 'Operaciones', ta: 'செயல்பாடுகள்', te: 'ఆపరేషన్స్', kn: 'ಕಾರ್ಯಾಚರಣೆಗಳು', ml: 'ഓപ്പറേഷനുകൾ' },
  'recovery.title': { en: 'Recovery Queue', hi: 'रिकवरी कतार', es: 'Cola de recuperación', ta: 'மீட்பு வரிசை', te: 'రికవరీ క్యూ', kn: 'ಮರುಪಡೆಯುವಿಕೆ ಸರತಿ', ml: 'വീണ്ടെടുക്കൽ ക്യൂ' },
  'recovery.subtitle': { en: 'Reasons: corrupt · too_short · missing · cut_off. A lost recording is a compliance failure — resolve every item.', hi: 'कारण: corrupt · too_short · missing · cut_off। खोई हुई रिकॉर्डिंग एक अनुपालन विफलता है — हर आइटम हल करें।', es: 'Motivos: corrupt · too_short · missing · cut_off. Una grabación perdida es una falla de cumplimiento; resuelve cada elemento.', ta: 'காரணங்கள்: corrupt · too_short · missing · cut_off. இழந்த பதிவு ஒரு இணக்கத் தோல்வி — ஒவ்வொரு உருப்படியையும் தீர்க்கவும்.', te: 'కారణాలు: corrupt · too_short · missing · cut_off. కోల్పోయిన రికార్డింగ్ కంప్లయన్స్ వైఫల్యం — ప్రతి అంశాన్ని పరిష్కరించండి.', kn: 'ಕಾರಣಗಳು: corrupt · too_short · missing · cut_off. ಕಳೆದುಹೋದ ರೆಕಾರ್ಡಿಂಗ್ ಅನುಸರಣೆ ವೈಫಲ್ಯ — ಪ್ರತಿ ಐಟಂ ಅನ್ನು ಪರಿಹರಿಸಿ.', ml: 'കാരണങ്ങൾ: corrupt · too_short · missing · cut_off. നഷ്ടപ്പെട്ട റെക്കോർഡിംഗ് ഒരു കംപ്ലയൻസ് പരാജയമാണ് — ഓരോ ഇനവും പരിഹരിക്കുക.' },
  'recovery.customer': { en: 'Customer', hi: 'ग्राहक', es: 'Cliente', ta: 'வாடிக்கையாளர்', te: 'కస్టమర్', kn: 'ಗ್ರಾಹಕ', ml: 'ഉപഭോക്താവ്' },
