  'recovery.actions': { en: 'Actions', hi: 'कार्रवाई', es: 'Acciones', ta: 'செயல்கள்', te: 'చర్యలు', kn: 'ಕ್ರಿಯೆಗಳು', ml: 'പ്രവർത്തനങ്ങൾ' },
  'recovery.restitch': { en: 'Re-stitch', hi: 'फिर से जोड़ें', es: 'Reunir de nuevo', ta: 'மீண்டும் இணை', te: 'మళ్లీ కుట్టండి', kn: 'ಮತ್ತೆ ಜೋಡಿಸಿ', ml: 'വീണ്ടും തുന്നുക' },
  'recovery.resolved': { en: 'Resolved', hi: 'हल हो गया', es: 'Resuelto', ta: 'தீர்க்கப்பட்டது', te: 'పరిష్కరించబడింది', kn: 'ಪರಿಹರಿಸಲಾಗಿದೆ', ml: 'പരിഹരിച്ചു' },
  'recovery.unrecoverable': { en: 'Unrecoverable', hi: 'अपूरणीय', es: 'Irrecuperable', ta: 'மீட்க முடியாதது', te: 'తిరిగి పొందలేనిది', kn: 'ಮರುಪಡೆಯಲಾಗದ', ml: 'വീണ്ടെടുക്കാനാവാത്തത്' },
