export type DictionaryKey = keyof typeof dictionary;

/** Substitutes {placeholders} in a translated string with the given values. */
export function interpolate(template: string, vars?: Record<string, string | number>): string {
  if (!vars) return template;
  return template.replace(/\{(\w+)\}/g, (match, key) => (key in vars ? String(vars[key]) : match));
}

export function translate(locale: UiLocale, key: DictionaryKey, vars?: Record<string, string | number>): string {
  const entry = dictionary[key] as Record<string, string>;
  const template = entry[locale] ?? entry.en ?? key;
  return interpolate(template, vars);
}
